import java.util.*;

class Solution {
  public int minNumberOfSemesters(int n, int[][] relations, int k) {
    int[] pre = new int[n];
    for (int[] r : relations) pre[r[1] - 1] |= 1 << (r[0] - 1);
    int size = 1 << n;
    int[] dp = new int[size];
    Arrays.fill(dp, n + 1);
    dp[0] = 0;
    for (int mask = 0; mask < size; mask++) {
      if (dp[mask] > n) continue;
      int available = 0;
      for (int i = 0; i < n; i++)
        if ((mask & (1 << i)) == 0 && (pre[i] & mask) == pre[i]) available |= 1 << i;
      for (int take = available; take > 0; take = (take - 1) & available)
        if (Integer.bitCount(take) <= k) dp[mask | take] = Math.min(dp[mask | take], dp[mask] + 1);
    }
    return dp[size - 1];
  }
}
